lass="field"><div>Wiedervorlage am</div><div class="value">{{ $rechnung->datRechnungStrittigWiedervorlage ? date('d.m.Y',strtotime($rechnung->datRechnungStrittigWiedervorlage)) : '' }}</div></div><div class="field full"><div>Grund</div><div class="value">{{ $rechnung->strRechnungStrittigGrund ?: '-' }}</div></div><div class="field full"><div>Zahlungskommentar</div><div class="value">{{ $rechnung->strZahlungskommentar ?: '-' }}</div></div></div><p>@if($rechnung->strPfadZurRechnung)<a class="button" href="{{ route('rechnungen.file',$rechnung->intID) }}" target="_blank">Rechnung öffnen</a> <button class="button" type="button" onclick="copyInvoicePath(this)">Pfad kopieren</button> @endif<a class="button" href="{{ route('rechnungen.index') }}">Zur Rechnungsübersicht</a>@if($kunde && $auftrag) <a class="button" href="{{ route('kunden.auftraege.show',[$kunde->intID,$auftrag->intAufNr]) }}">Auftrag öffnen</a>@endif</p><p class="muted">Bestehende Rechnungs-, Zahlungs- und Mahndaten sind in dieser Ansicht bewusst nur lesend. Rechnungsdateien werden über den read-only eingebundenen Serverpfad bereitgestellt.</p></div><script>async function copyInvoicePath(button){const path=document.getElementById('invoice-path').innerText.trim();let copied=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(path);copied=true}}catch(e){}if(!copied){const field=document.createElement('textarea');field.value=path;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();try{copied=document.execCommand('copy')}catch(e){}field.remove()}const original='Pfad kopieren';button.textContent=copied?'Pfad kopiert':'Kopieren fehlgeschlagen';setTimeout(()=>button.textContent=original,2000)}</script><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>